/** Genuine separate-JVM ordinary save/load. Expectation NBT stores identities/scalars, never reconstructed entity payloads. */
@GameTestHolder("dreamseekers_fox_spore_restart")
@PrefixGameTestTemplate(false)
public final class FoxSporeSkillRestartGameTests {
    private static final String OWNER="FoxSporeRestart_Owner",ENEMY="FoxSporeRestart_Enemy";
    private static final BlockPos ORIGIN=new BlockPos(57344,90,57344);
    private static final File MANIFEST=new File("fox-spore-skill-restart-expectations.nbt");
    private static final UUID PERMANENT=UUID.fromString("e3dc7fbf-fdca-41f9-ae12-3e7f67c2cd28");
    private static final List<String> KEYS=List.of("spentFox","beneficiary","unusedFox","ordinaryShooter");
    private static final Map<String,FakePlayer> PLAYERS=new HashMap<>();
    @GameTest(template="unit_isolation_arena",batch="dreamseekers_fox_spore_restart",timeoutTicks=1600)
    public static void ordinaryRestartRetainsBothPaidCooldownsButNeverReplaysLeaseEffectsOrSavedShotIntent(GameTestHelper h) throws Exception {
        switch(System.getProperty("dreamseekers.fox.spore.test.phase","")){case "prepare"->prepare(h);case "verify"->verify(h);default->throw new IllegalArgumentException("Unknown Fox spore restart phase");}
    }
    private static void prepare(GameTestHelper h){
        ServerLevel level=h.getLevel();h.assertTrue(!MANIFEST.exists()&&PlayerServerEvents.getRTSPlayer(OWNER)==null,"fresh isolated spore prepare world");CompoundTag expected=new CompoundTag();expected.putLong("prepareJvmStart",java.lang.management.ManagementFactory.getRuntimeMXBean().getStartTime());List<Long> forced=new ArrayList<>();for(int x=3584;x<=3586;x++)for(int z=3584;z<=3586;z++){long key=ChunkPos.asLong(x,z);h.assertTrue(!level.getForcedChunks().contains(key),"never adopt another fixture's forced chunk");level.setChunkForced(x,z,true);forced.add(key);}expected.putLongArray("forcedChunks",forced);arena(level);register(OWNER);register(ENEMY);player(level,OWNER);player(level,ENEMY);
        Map<String,Mob> units=new LinkedHashMap<>();units.put("spentFox",DreamseekersMod.GOLDEN_FOX_UNIT.get().create(level));units.put("beneficiary",DreamseekersMod.PINK_SLIME_UNIT.get().create(level));units.put("unusedFox",DreamseekersMod.GOLDEN_FOX_UNIT.get().create(level));units.put("ordinaryShooter",EntityRegistrar.SKELETON_UNIT.get().create(level));int[][] positions={{4,1,8},{8,1,10},{18,1,25},{4,1,8}};
        int index=0;for(var entry:units.entrySet()){Mob body=entry.getValue();Unit unit=(Unit)body;unit.setOwnerName(entry.getKey().equals("ordinaryShooter")?ENEMY:OWNER);unit.setScenarioRoleIndex(1801+index);int[] p=positions[index++];move(body,p[0],p[1],p[2]);body.setNoAi(true);if(body.getAttribute(AttributeRegistrar.AGGRO_RANGE.get())!=null)body.getAttribute(AttributeRegistrar.AGGRO_RANGE.get()).setBaseValue(0);h.assertTrue(level.addFreshEntity(body),"actual registered body enters ordinary world entity storage");expected.putUUID(entry.getKey(),body.getUUID());}
        var beneficiary=(PinkSlimeUnit)units.get("beneficiary");beneficiary.getAttribute(AttributeRegistrar.ATTACKS_PER_SECOND.get()).addPermanentModifier(new AttributeModifier(PERMANENT,"permanent restart research",.1,AttributeModifier.Operation.ADDITION));var shooter=(com.solegendary.reignofnether.unit.units.monsters.SkeletonUnit)units.get("ordinaryShooter");shooter.setupEquipmentAndUpgradesServer();shooter.getAttribute(AttributeRegistrar.ATTACK_DAMAGE.get()).setBaseValue(4);shooter.getAttribute(AttributeRegistrar.CRITICAL_HIT_CHANCE.get()).setBaseValue(0);JungleSporeCarrier[] carrier={null};Arrow[] old={null};
        h.startSequence().thenWaitUntil(()->{for(Mob body:units.values())published(h,level,body);for(FakePlayer p:PLAYERS.values())published(h,level,p);h.assertTrue(level.isPositionEntityTicking(at(10,1,8))&&level.areEntitiesLoaded(new ChunkPos(at(10,1,8)).toLong()),"actual destination entity data ready before birth");})
          .thenExecute(()->{ledger(h);h.assertTrue(beneficiary.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN,8000))&&beneficiary.addEffect(new MobEffectInstance(MobEffects.WEAKNESS,8000)),"native eligible effects precede real activation");var fox=(GoldenFoxUnit)units.get("spentFox");h.assertTrue(seed(level,fox,at(10,1,8))==SkillResult.SUCCESS,"real authenticated seed spends its independent cooldown");carrier[0]=SporeLease.activeFor(fox);h.assertTrue(carrier[0]!=null&&!beneficiary.hasEffect(MobEffects.MOVEMENT_SLOWDOWN)&&beneficiary.hasEffect(MobEffects.WEAKNESS)&&SporeEffects.cleanseProtectionTicks(beneficiary)==200,"actual activation cleansed only selected effect and created live protection");h.assertTrue(beneficiary.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN,1000))&&beneficiary.getEffect(MobEffects.MOVEMENT_SLOWDOWN).getDuration()==800,"real incoming effect duration1000 becomes800 exactly once before save");h.assertTrue(bless(level,fox)==SkillResult.SUCCESS&&SkillEffects.bonus(beneficiary,BuffKind.ATTACK_SPEED)==.20,"same source genuinely spends separate blessing cooldown and buffs actual allied fighter");h.assertTrue(command(h,player(level,ENEMY),shooter,UnitAction.ATTACK,carrier[0]),"real enemy owner's accepted ATTACK selects actual lease before original arrow factory");})
          .thenWaitUntil(()->directed(h,shooter,carrier[0]))
          .thenExecute(()->{shooter.performUnitRangedAttack(carrier[0],1);for(Entity e:level.getAllEntities())if(e instanceof Arrow arrow&&arrow.getOwner()==shooter&&!arrow.isRemoved()){h.assertTrue(old[0]==null,"exactly one genuine prepare factory arrow");old[0]=arrow;}h.assertTrue(old[0]!=null&&level.getEntity(old[0].getId())==old[0]&&OrdinarySkillHit.mayHitSpore(old[0],carrier[0]),"actual published ordinary factory arrow held real selected-lease intent before save");move(old[0],22,4,25);old[0].setDeltaMovement(Vec3.ZERO);old[0].setNoGravity(true);expected.putUUID("savedArrow",old[0].getUUID());expected.putUUID("savedCarrier",carrier[0].getUUID());expected.putLong("snapshotGameTime",level.getGameTime());expected.putInt("savedSlowDuration",beneficiary.getEffect(MobEffects.MOVEMENT_SLOWDOWN).getDuration());h.assertTrue(SporeLease.active(carrier[0])&&SporeEffects.cleanseProtectionTicks(beneficiary)>0&&SkillEffects.bonus(beneficiary,BuffKind.ATTACK_SPEED)>.19,"ordinary save snapshot contains genuinely live lease, protection and temporary buff");
            for(var entry:units.entrySet()){Mob body=entry.getValue();Unit unit=(Unit)body;CompoundTag state=new CompoundTag();state.putString("owner",unit.getOwnerName());state.putInt("scenario",unit.getScenarioRoleIndex());state.putFloat("health",body.getHealth());state.putDouble("baseAPS",body.getAttribute(AttributeRegistrar.ATTACKS_PER_SECOND.get()).getBaseValue());if(body instanceof SkillUnit skill){state.putLong("revision",skill.rts().skills().revision());state.putInt("seedCD",skill.rts().skills().cooldownTicks(UnitSkill.FOX_DREAM_SEED));state.putInt("blessCD",skill.rts().skills().cooldownTicks(UnitSkill.FOX_BLESSING));}expected.put(entry.getKey()+"State",state);}h.assertTrue(expected.getCompound("spentFoxState").getInt("seedCD")>0&&expected.getCompound("spentFoxState").getInt("blessCD")>0,"both independently paid cooldowns still live");ledger(h);try{NbtIo.writeCompressed(expected,MANIFEST);}catch(Exception failure){throw new RuntimeException(failure);}System.out.println("DREAMSEEKERS_FOX_SPORE_RESTART_PREPARED gameTime="+level.getGameTime()+" seedCD="+expected.getCompound("spentFoxState").getInt("seedCD")+" blessCD="+expected.getCompound("spentFoxState").getInt("blessCD")+" carrier="+carrier[0].getUUID()+" savedArrow="+old[0].getUUID()+" slow="+expected.getInt("savedSlowDuration"));}).thenSucceed();
    }
    private static void verify(GameTestHelper h) throws Exception {
        ServerLevel level=h.getLevel();h.assertTrue(MANIFEST.isFile(),"normal prepare manifest present");CompoundTag expected=NbtIo.readCompressed(MANIFEST);h.assertTrue(expected.getLong("prepareJvmStart")!=java.lang.management.ManagementFactory.getRuntimeMXBean().getStartTime(),"actual second JVM, never same-process NBT stand-in");for(long packed:expected.getLongArray("forcedChunks")){h.assertTrue(level.getForcedChunks().contains(packed),"ordinary save restored exact forced chunks");ChunkPos chunk=new ChunkPos(packed);level.getChunk(chunk.x,chunk.z);}player(level,OWNER);player(level,ENEMY);Map<String,Mob> units=new LinkedHashMap<>();Arrow[] old={null};JungleSporeCarrier[] fresh={null};Vec3[] oldRelease={null};
        h.startSequence().thenWaitUntil(()->{for(String key:KEYS){Entity body=level.getEntity(expected.getUUID(key));h.assertTrue(body instanceof Mob&&body instanceof Unit,"actual normal world loaded original UUID: "+key);published(h,level,body);}Entity arrow=level.getEntity(expected.getUUID("savedArrow"));h.assertTrue(arrow instanceof Arrow,"real saved factory projectile restored with original UUID");published(h,level,arrow);for(FakePlayer p:PLAYERS.values())published(h,level,p);h.assertTrue(level.isPositionEntityTicking(at(24,1,25))&&level.areEntitiesLoaded(new ChunkPos(at(24,1,25)).toLong()),"new target chunk has actual entity-ticking data before fresh birth");})
          .thenExecute(()->{ledger(h);long elapsed=level.getGameTime()-expected.getLong("snapshotGameTime");h.assertTrue(elapsed>=0&&elapsed<400,"actual cross-JVM observation occurs while both paid480 cooldowns and long negative effect can still be meaningfully tested, elapsed="+elapsed);for(String key:KEYS){Mob body=(Mob)level.getEntity(expected.getUUID(key));units.put(key,body);body.setNoAi(true);Unit unit=(Unit)body;CompoundTag state=expected.getCompound(key+"State");h.assertTrue(unit.getOwnerName().equals(state.getString("owner"))&&unit.getScenarioRoleIndex()==state.getInt("scenario"),"ordinary owner/scenario survives: "+key);close(h,body.getHealth(),state.getFloat("health"),"no replay or spontaneous normal idle attack before verification: "+key);close(h,body.getAttribute(AttributeRegistrar.ATTACKS_PER_SECOND.get()).getBaseValue(),state.getDouble("baseAPS"),"permanent base APS retained: "+key);h.assertTrue(UnitServerEvents.getAllUnits().stream().filter(e->e.getUUID().equals(body.getUUID())).count()==1,"exactly one original unit UUID in ordinary roster: "+key);h.assertTrue(SporeEffects.cleanseProtectionTicks(body)==0&&SkillEffects.bonus(body,BuffKind.ATTACK_SPEED)==0,"short successful throttle and ordinary buff are not replayed: "+key);if(body instanceof SkillUnit skill){for(UnitSkill kind:List.of(UnitSkill.FOX_DREAM_SEED,UnitSkill.FOX_BLESSING)){String field=kind==UnitSkill.FOX_DREAM_SEED?"seedCD":"blessCD";int remaining=(int)Math.max(0,expected.getLong("snapshotGameTime")+state.getInt(field)-level.getGameTime());h.assertTrue(skill.rts().skills().cooldownTicks(kind)==remaining,"independent paid absolute cooldown neither refunded nor reset: "+key+" "+kind);}h.assertTrue(skill.rts().skills().revision()>=state.getLong("revision"),"shared replay revision never rewinds");}}
            Entity oldCarrier=level.getEntity(expected.getUUID("savedCarrier"));h.assertTrue(oldCarrier==null||oldCarrier.isRemoved()||oldCarrier instanceof JungleSporeCarrier c&&!SporeLease.active(c),"saved old carrier has no activation lease");h.assertTrue(SporeLease.activeCount(OWNER)==0&&SporeLease.activeFor((GoldenFoxUnit)units.get("spentFox"))==null,"restart created no duplicate or restored lease");var beneficiary=(PinkSlimeUnit)units.get("beneficiary");h.assertTrue(beneficiary.getAttribute(AttributeRegistrar.ATTACKS_PER_SECOND.get()).getModifier(PERMANENT)!=null,"actual permanent research modifier survived");close(h,beneficiary.getAttributeValue(AttributeRegistrar.ATTACKS_PER_SECOND.get()),expected.getCompound("beneficiaryState").getDouble("baseAPS")+.1,"only permanent research remains; no temporary blessing modifier");h.assertTrue(beneficiary.hasEffect(MobEffects.WEAKNESS),"unselected long negative effect was not cleansed again on restart");var slow=beneficiary.getEffect(MobEffects.MOVEMENT_SLOWDOWN);int savedDuration=expected.getInt("savedSlowDuration");h.assertTrue(slow!=null&&slow.getDuration()<=savedDuration&&slow.getDuration()>=savedDuration-elapsed-2,"native saved once-shortened effect continues ordinary ticking, never reapplies0.8 on load: saved="+savedDuration+" now="+(slow==null?-1:slow.getDuration())+" elapsed="+elapsed);beneficiary.removeEffect(MobEffects.MOVEMENT_SLOWDOWN);h.assertTrue(beneficiary.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN,100))&&beneficiary.getEffect(MobEffects.MOVEMENT_SLOWDOWN).getDuration()==100,"fresh native incoming100 near old location is not shortened by an absent saved aura");
            var spent=(GoldenFoxUnit)units.get("spentFox");h.assertTrue(spent.rts().skills().cooldownTicks(UnitSkill.FOX_DREAM_SEED)>0&&spent.rts().skills().cooldownTicks(UnitSkill.FOX_BLESSING)>0,"both spent cooldowns remain live in true second JVM");h.assertTrue(seed(level,spent,at(10,1,8))!=SkillResult.SUCCESS&&bless(level,spent)!=SkillResult.SUCCESS,"neither paid active can be replayed for free");var unused=(GoldenFoxUnit)units.get("unusedFox");h.assertTrue(seed(level,unused,at(24,1,25))==SkillResult.SUCCESS,"real unused caster can make a fresh post-restart lease");fresh[0]=SporeLease.activeFor(unused);h.assertTrue(fresh[0]!=null&&fresh[0].getHealth()==10,"fresh carrier truly activated");old[0]=(Arrow)level.getEntity(expected.getUUID("savedArrow"));h.assertTrue(old[0].getOwner()==units.get("ordinaryShooter")&&!OrdinarySkillHit.mayHitSpore(old[0],fresh[0]),"real original projectile owner resolves but saved shot intent never authorizes a fresh lease");oldRelease[0]=old[0].position();Vec3 vector=fresh[0].getBoundingBox().getCenter().subtract(old[0].position());old[0].setNoGravity(true);old[0].shoot(vector.x,vector.y,vector.z,1.6f,0);})
          .thenIdle(35).thenExecute(()->{h.assertTrue(old[0].position().distanceTo(oldRelease[0])>2,"same physically saved original arrow really traversed the fresh target direction");close(h,fresh[0].getHealth(),10,"loaded old shot cannot borrow new lease intent even with genuine restored owner");Mob shooter=units.get("ordinaryShooter");move(shooter,18,1,25);move(units.get("unusedFox"),18,1,30);h.assertTrue(command(h,player(level,ENEMY),shooter,UnitAction.ATTACK,fresh[0]),"genuinely new authenticated explicit target order after old-shot denial");})
          .thenWaitUntil(()->directed(h,units.get("ordinaryShooter"),fresh[0]))
          .thenExecute(()->{((RangedAttackerUnit)units.get("ordinaryShooter")).performUnitRangedAttack(fresh[0],1);})
          .thenIdle(45).thenExecute(()->{close(h,fresh[0].getHealth(),6,"new accepted order and actual native factory regain lawful four-HP primary after restart");h.assertTrue(SporeLease.active(fresh[0]),"positive is physical damage, not expiration");ledger(h);System.out.println("DREAMSEEKERS_FOX_SPORE_RESTART_UUID_TWO_COOLDOWNS_NO_REPLAY_PASS elapsedWorldTicks="+(level.getGameTime()-expected.getLong("snapshotGameTime"))+" seedCD="+((GoldenFoxUnit)units.get("spentFox")).rts().skills().cooldownTicks(UnitSkill.FOX_DREAM_SEED)+" blessCD="+((GoldenFoxUnit)units.get("spentFox")).rts().skills().cooldownTicks(UnitSkill.FOX_BLESSING)+" oldArrow="+old[0].getUUID());for(Mob body:units.values())body.discard();if(!old[0].isRemoved())old[0].discard();for(FakePlayer p:List.copyOf(PLAYERS.values()))p.serverLevel().removePlayerImmediately(p,Entity.RemovalReason.DISCARDED);PLAYERS.clear();PlayerServerEvents.players.removeIf(p->p.getGameProfile().getName().equals(OWNER)||p.getGameProfile().getName().equals(ENEMY));PlayerServerEvents.rtsPlayers.removeIf(p->p.name.equals(OWNER)||p.name.equals(ENEMY));ResourcesServerEvents.resourcesList.removeIf(r->r.ownerName.equals(OWNER)||r.ownerName.equals(ENEMY));for(long packed:expected.getLongArray("forcedChunks")){ChunkPos chunk=new ChunkPos(packed);level.setChunkForced(chunk.x,chunk.z,false);}}).thenSucceed();
    }
    private static SkillResult seed(ServerLevel level,GoldenFoxUnit source,BlockPos ground){return SkillService.requestGround(player(level,source.getOwnerName()),new SkillGroundRequest(UnitSkill.FOX_DREAM_SEED,source.getId(),source.getUUID(),source.rts().skills().revision(),ground));}
    private static SkillResult bless(ServerLevel level,GoldenFoxUnit source){return SkillService.request(player(level,source.getOwnerName()),new SkillRequest(UnitSkill.FOX_BLESSING,source.getId(),source.getUUID(),source.rts().skills().revision(),source.getId(),source.getUUID()));}
    private static boolean command(GameTestHelper h,ServerPlayer sender,Mob source,UnitAction action,LivingEntity target){try{var connection=new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);connection.setListener(sender.connection);var constructor=net.minecraftforge.network.NetworkEvent.Context.class.getDeclaredConstructor(net.minecraft.network.Connection.class,net.minecraftforge.network.NetworkDirection.class,int.class);constructor.setAccessible(true);var context=constructor.newInstance(connection,net.minecraftforge.network.NetworkDirection.PLAY_TO_SERVER,-1);h.assertTrue(context.getSender()==sender,"exact actual authenticated server sender");return new com.solegendary.reignofnether.unit.packets.UnitActionServerboundPacket(((Unit)source).getOwnerName(),action,target.getId(),new int[]{source.getId()},target.blockPosition(),BlockPos.ZERO,false).handle(()->context);}catch(ReflectiveOperationException failure){throw new RuntimeException("actual restart command context",failure);}}
    private static void directed(GameTestHelper h,Mob source,LivingEntity target){h.assertTrue(!UnitServerEvents.hasPendingImmediateAction(source.getId())&&((Unit)source).getTargetGoal().forced&&((Unit)source).getTargetGoal().getTarget()==target,"real explicit command executed against exact actual target");}
    private static void register(String owner){PlayerServerEvents.rtsPlayers.add(RTSPlayer.getNewBot(owner,DreamseekersMod.DREAMSEEKERS));ResourcesServerEvents.resourcesList.add(new Resources(owner,123,234,345,456));}
    private static FakePlayer player(ServerLevel level,String owner){return PLAYERS.computeIfAbsent(owner,key->{var p=new FakePlayer(level,new GameProfile(UUID.nameUUIDFromBytes(key.getBytes(java.nio.charset.StandardCharsets.UTF_8)),key));p.connection=new SilentHandler(p);move(p,2,1,42);level.addNewPlayer(p);PlayerServerEvents.players.add(p);return p;});}
    private static void published(GameTestHelper h,ServerLevel level,Entity e){h.assertTrue(e.tickCount>3&&level.getEntity(e.getId())==e&&level.getEntity(e.getUUID())==e,"normal published identity and actual entity ticks: "+e.getUUID()+" ticks="+e.tickCount);}
    private static BlockPos at(int x,int y,int z){return ORIGIN.offset(x,y,z);}
    private static void move(Entity e,int x,int y,int z){e.moveTo(ORIGIN.getX()+x+.5,ORIGIN.getY()+y,ORIGIN.getZ()+z+.5);e.setDeltaMovement(Vec3.ZERO);}
    private static void close(GameTestHelper h,double actual,double expected,String why){h.assertTrue(Double.isFinite(actual)&&Math.abs(actual-expected)<.0005,why+": expected="+expected+" actual="+actual);}
    private static void ledger(GameTestHelper h){for(String owner:List.of(OWNER,ENEMY)){var resource=ResourcesServerEvents.resourcesList.stream().filter(r->r.ownerName.equals(owner)).findFirst().orElse(null);h.assertTrue(resource!=null,"original fixture ledger account must exist: "+owner);System.out.println("FOX_SPORE_RESTART_LEDGER gameTime="+h.getLevel().getGameTime()+" owner="+owner+" bank="+resource.food+","+resource.wood+","+resource.ore+","+resource.emerald+" pending="+resource.foodToAdd+","+resource.woodToAdd+","+resource.oreToAdd+","+resource.emeraldToAdd+" cargo="+UnitServerEvents.getAllUnits().stream().filter(e->e instanceof Unit u&&u.getOwnerName().equals(owner)).map(e->e.getUUID()+":"+((Unit)e).getItems()).toList());h.assertTrue(resource.food==123&&resource.wood==234&&resource.ore==345&&resource.emerald==456,"all ordinary resources unchanged; no balancing or forgiving known historical food drift");h.assertTrue(resource.foodToAdd==0&&resource.woodToAdd==0&&resource.oreToAdd==0&&resource.emeraldToAdd==0,"no pending ledger settlement");for(LivingEntity e:UnitServerEvents.getAllUnits())if(e instanceof Unit unit&&unit.getOwnerName().equals(owner))h.assertTrue(unit.getItems().isEmpty(),"unit cargo empty, never cleared as test cleanup: "+e.getUUID()+" "+unit.getItems());}}
    private static void arena(ServerLevel level){for(int x=0;x<46;x++)for(int z=0;z<46;z++)level.setBlock(at(x,9,z),Blocks.STONE.defaultBlockState(),2);level.getEntitiesOfClass(net.minecraft.world.entity.item.FallingBlockEntity.class,new AABB(ORIGIN.getX(),ORIGIN.getY()+1,ORIGIN.getZ(),ORIGIN.getX()+46,level.getMaxBuildHeight(),ORIGIN.getZ()+46)).forEach(Entity::discard);for(int x=0;x<46;x++)for(int z=0;z<46;z++){level.setBlock(at(x,0,z),Blocks.STONE.defaultBlockState(),2);for(int y=1;y<9;y++)level.setBlock(at(x,y,z),(x==0||x==45||z==0||z==45?Blocks.STONE:Blocks.AIR).defaultBlockState(),2);}var drops=level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(ORIGIN,ORIGIN.offset(46,10,46)));System.out.println("FOX_SPORE_RESTART_CONSTRUCTION_DROPS_REMOVED count="+drops.size());drops.forEach(Entity::discard);}
    private static final class SilentHandler extends ServerGamePacketListenerImpl{SilentHandler(ServerPlayer player){super(player.serverLevel().getServer(),new SilentConnection(),player);}@Override public void tick(){}@Override public void send(net.minecraft.network.protocol.Packet<?> packet){}@Override public void send(net.minecraft.network.protocol.Packet<?> packet,net.minecraft.network.PacketSendListener listener){}}
    private static final class SilentConnection extends net.minecraft.network.Connection{SilentConnection(){super(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);}@Override public void tick(){}@Override public void send(net.minecraft.network.protocol.Packet<?> packet){}@Override public void send(net.minecraft.network.protocol.Packet<?> packet,net.minecraft.network.PacketSendListener listener){}}
}
